INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(17540705, 'Performapal Dag Daggerman', '娱乐伙伴 奇人飞剑手', 'EMダグ・ダガーマン', 'Pendulum Effect Monster', 'Warrior', 'EARTH', 5, 2000, 600, '「娱乐伙伴 奇人飞剑手」的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤成功的回合的自己主要阶段从手卡把1只「娱乐伙伴」怪兽送去墓地才能发动。自己从卡组抽1张。'),
(55553602, 'Performapal Dramatic Theater', '娱乐伙伴戏剧剧场', 'EMドラマチックシアター', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的怪兽的攻击力上升自己场上的怪兽的种族种类×200。 ②：1回合1次，自己场上的「娱乐伙伴」怪兽的种族是4种类的场合才能发动。从自己的手卡·卡组·墓地选1只「异色眼」怪兽特殊召唤。'),
(70479321, 'Performapal Drummerilla', '娱乐伙伴 打鼓金刚', 'EMドラミング・コング', 'Pendulum Effect Monster', 'Beast', 'EARTH', 5, 1600, 900, '①：双方场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：不用解放作召唤的这张卡的等级变成4星。 ③：1回合1次，自己怪兽和对方怪兽进行战斗的攻击宣言时，以那1只自己怪兽为对象才能发动。那只怪兽的攻击力直到战斗阶段结束时上升600。'),
(92644052, 'Performapal Duelist Extraordinaire', '娱乐伙伴 稀代的决斗者', 'EM稀代の決闘者', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 400, '①：这张卡给与对方战斗伤害时才能发动。从卡组把1只「霸王眷龙」怪兽或者「霸王门」怪兽或者1张「霸王龙之魂」加入手卡。 ②：自己·对方的准备阶段发动。双方各自可以从自身卡组把1张魔法卡除外。 ③：1回合1次，自己或者对方的怪兽的攻击宣言时发动。被攻击的玩家可以让以下效果适用。 ●选除外的1张自身的魔法卡加入手卡。那之后，那张卡丢弃，那次攻击无效。'),
(340002, 'Performapal Elephammer', '娱乐伙伴 槌子巨象', 'EMハンマーマンモ', 'Effect Monster', 'Beast', 'EARTH', 6, 2600, 1800, '①：自己场上有「娱乐伙伴」卡2张以上存在的场合，这张卡可以不用解放作召唤。 ②：自己场上没有其他的「娱乐伙伴」卡存在的场合，这张卡不能攻击。 ③：这张卡的攻击宣言时才能发动。对方场上的魔法·陷阱卡全部回到持有者手卡。'),
(45591967, 'Performapal Extra Slinger', '娱乐伙伴 额外射手', 'EMエクストラ・シューター', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 3, 800, 1100, '①：1回合1次，从自己的额外卡组把1只怪兽除外，以自己或者对方的灵摆区域1张卡为对象才能发动。那张卡破坏，给与对方300伤害。'),
(33823832, 'Performapal Fire Mufflerlion', '娱乐伙伴 火围巾狮', 'EMファイア・マフライオ', 'Pendulum Effect Monster', 'Beast', 'FIRE', 3, 800, 800, '①：1回合1次，自己的灵摆怪兽战斗破坏对方怪兽的伤害计算后才能发动。那只自己怪兽直到战斗阶段结束时攻击力上升200，只再1次可以继续攻击。'),
(12255007, 'Performapal Fireflux', '娱乐伙伴 灯泡萤火虫', 'EMホタルクス', 'Pendulum Effect Monster', 'Insect', 'LIGHT', 4, 1200, 1600, '①：只要这张卡在怪兽区域存在，自己场上的「娱乐伙伴」怪兽或者「异色眼」怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(19619755, 'Performapal Five-Rainbow Magician', '娱乐伙伴 五虹之魔术师', 'EM五虹の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 1, 100, 100, '①：这张卡在墓地存在，自己场上有魔法·陷阱卡被盖放的场合才能发动。墓地的这张卡在自己的灵摆区域放置。'),
(91449532, 'Performapal Flip Hippo', '娱乐伙伴 合掩河马', 'EMオールカバー・ヒッポ', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 800, '①：这张卡召唤成功时才能发动。从手卡把1只「娱乐伙伴」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果直到回合结束时无效化。 ②：1回合1次，自己主要阶段才能发动。自己场上的怪兽全部变成守备表示。'),
(96606246, 'Performapal Friendonkey', '娱乐伙伴 助手驴', 'EMフレンドンキー', 'Effect Monster', 'Beast', 'EARTH', 3, 1600, 600, '①：这张卡召唤成功时才能发动。从自己的手卡·墓地选1只4星以下的「娱乐伙伴」怪兽特殊召唤。'),
(49820233, 'Performapal Gatlinghoul', '娱乐伙伴 加特林食尸鬼', 'EMガトリングール', 'Fusion Monster', 'Fiend', 'DARK', 8, 2900, 900, '「娱乐伙伴」怪兽＋5星以上的暗属性怪兽 「娱乐伙伴 机炮食尸鬼」的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合才能发动。给与对方为场上的卡数量×200伤害。这张卡用灵摆怪兽为素材作融合召唤的场合，再选对方场上1只怪兽破坏，给与对方那只怪兽的原本攻击力数值的伤害。'),
(21949879, 'Performapal Gentrude', '娱乐伙伴 粗鲁先生', 'EMジェントルード', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1500, 1000, '这个卡名的①②的怪兽效果1回合只能有1次使用其中任意1个。 ①：这张卡被破坏的场合才能发动。从卡组选「娱乐伙伴 粗鲁先生」以外的1只「娱乐伙伴」灵摆怪兽在自己的灵摆区域放置。 ②：这张卡在额外卡组表侧表示存在的场合，从手卡丢弃1只灵摆怪兽才能发动。这张卡加入手卡。那之后，可以选自己的灵摆区域1张「娱乐伙伴」卡或者「异色眼」卡回到持有者手卡。'),
(64207696, 'Performapal Gold Fang', '娱乐伙伴 金牙狼', 'EMゴールド・ファング', 'Pendulum Effect Monster', 'Beast', 'LIGHT', 4, 1800, 700, '①：这张卡召唤·特殊召唤成功的场合发动。自己场上的「娱乐伙伴」怪兽的攻击力直到回合结束时上升200。'),
(9106362, 'Performapal Gongato', '娱乐伙伴 铜锣野猫', 'EMドラネコ', 'Pendulum Effect Monster', 'Beast', 'EARTH', 1, 100, 100, '①：1回合1次，自己怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(53724621, 'Performapal Guitartle', '娱乐伙伴 吉他海龟', 'EMギタートル', 'Pendulum Effect Monster', 'Aqua', 'WATER', 1, 300, 400, '①：1回合1次，以自己的灵摆区域1张卡为对象才能发动。那张卡的灵摆刻度直到回合结束时上升2。'),
(8384771, 'Performapal Gumgumouton', '娱乐伙伴 橡胶绵羊', 'EMゴムゴムートン', 'Pendulum Effect Monster', 'Beast', 'EARTH', 5, 900, 2400, '①：1回合1次，自己怪兽和对方怪兽进行战斗的攻击宣言时才能发动。那只自己怪兽不会被那次战斗破坏。'),
(55997110, 'Performapal Handsamuraiger', '娱乐伙伴 俊侍狮虎', 'EMハンサムライガー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1800, 400, '「娱乐伙伴 俊侍狮虎」的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只5星以上的灵摆怪兽加入手卡。'),
(81055000, 'Performapal Handstandaccoon', '娱乐伙伴 返回狸', 'EMリターンタンタン', 'Pendulum Effect Monster', 'Beast', 'EARTH', 2, 400, 600, '①：这张卡被战斗破坏时，以场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(88358139, 'Performapal Helpprincess', '娱乐伙伴 帮手公主', 'EMヘルプリンセス', 'Effect Monster', 'Warrior', 'DARK', 4, 1200, 1200, '①：自己对「娱乐伙伴 帮助公主」以外的「娱乐伙伴」怪兽的召唤·特殊召唤成功时才能发动。这张卡从手卡特殊召唤。'),
(41440148, 'Performapal Hip Hippo', '娱乐伙伴 探索河马', 'EMディスカバー・ヒッポ', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 800, '①：这张卡召唤成功的回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只7星以上的怪兽表侧攻击表示上级召唤。'),
(71985676, 'Performapal Inflater Tapir', '娱乐伙伴 障碍气球貘', 'EMバリアバルーンバク', 'Effect Monster', 'Beast', 'WIND', 6, 1000, 2000, '「娱乐伙伴 障碍气球貘」的②的效果1回合只能使用1次。 ①：自己怪兽和对方怪兽进行战斗的伤害计算时，把这张卡从手卡丢弃才能发动。那次战斗发生的双方的战斗伤害变成0。 ②：这张卡在墓地存在的场合，对方怪兽的直接攻击宣言时从手卡丢弃1只「娱乐伙伴」怪兽才能发动。这张卡从墓地守备表示特殊召唤。'),
(78835747, 'Performapal Kaleidoscorp', '娱乐伙伴 万花筒蝎', 'EMカレイドスコーピオン', 'Pendulum Effect Monster', 'Insect', 'LIGHT', 6, 100, 2300, '①：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽可以向对方场上的特殊召唤的怪兽全部各作1次攻击。'),
(67808837, 'Performapal King Bear', '娱乐伙伴 国王熊精', 'EMキングベアー', 'Pendulum Effect Monster', 'Beast-Warrior', 'EARTH', 6, 2200, 1000, '①：攻击表示的这张卡不会被魔法·陷阱卡的效果破坏。 ②：这张卡的攻击力在自己战斗阶段内上升自己场上的「娱乐伙伴」卡数量×100。'),
(69181753, 'Performapal Kuribohble', '娱乐伙伴 横条栗子球', 'EMクリボーダー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤，那只对方怪兽的攻击对象转移为这张卡进行伤害计算。那次战斗让自己受到战斗伤害的场合，作为代替让自己基本分回复那个数值。'),
(58938528, 'Performapal Ladyange', '娱乐伙伴 天使女士', 'EMレディアンジュ', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 3, 1000, 1500, '这个卡名的①②的怪兽效果1回合只能有1次使用其中任意1个。 ①：从手卡把「娱乐伙伴 天使女士」以外的1只「娱乐伙伴」怪兽和这张卡丢弃才能发动。自己从卡组抽2张。 ②：这张卡在墓地存在，自己场上有「异色眼」卡或者「娱乐伙伴 粗鲁先生」存在的场合才能发动。这张卡在自己的灵摆区域放置。'),
(44944304, 'Performapal Laugh Maker', '娱乐伙伴 逗乐家', 'EMラフメイカー', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2000, '「娱乐伙伴 逗乐家」的①②的怪兽效果1回合只能有1次使用其中任意1个。 ①：这张卡的攻击宣言时才能发动。这张卡的攻击力直到战斗阶段结束时上升这张卡以及对方场上的怪兽之内持有比原本攻击力高的攻击力的怪兽数量×1000。 ②：持有比原本攻击力高的攻击力的这张卡被战斗·效果破坏的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(3752422, 'Performapal Lebellman', '娱乐伙伴 调级钟行李员', 'EMレ・ベルマン', 'Pendulum Effect Monster', 'Fairy', 'LIGHT', 6, 100, 2600, '①：1回合1次，宣言1～5的任意等级，以这张卡以外的自己场上1只「娱乐伙伴」怪兽为对象才能发动。直到回合结束时，这张卡的等级下降宣言的等级数值，作为对象的怪兽的等级上升宣言的等级数值。'),
(7268133, 'Performapal Life Swordsman', '娱乐伙伴 生命剑士', 'EMライフ・ソードマン', 'Effect Monster', 'Warrior', 'LIGHT', 1, NULL, NULL, '①：对方基本分回复时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的攻击力变成和这个时候对方回复的数值相同。 ②：把这张卡解放，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。'),
(73130445, 'Performapal Lizardraw', '娱乐伙伴 抽卡蜥蜴', 'EMリザードロー', 'Pendulum Effect Monster', 'Reptile', 'EARTH', 3, 1200, 600, '「娱乐伙伴 抽卡蜥蜴」的怪兽效果1回合只能使用1次。 ①：这张卡以外的自己场上的表侧表示怪兽被对方怪兽的攻击或者对方的效果破坏的场合才能发动。自己从卡组抽出自己场上的「娱乐伙伴」怪兽的数量。'),
(92170894, 'Performapal Longphone Bull', '娱乐伙伴 电话长角牛', 'EMロングフォーン・ブル', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1200, '「娱乐伙伴 电话长角牛」的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把灵摆怪兽以外的1只「娱乐伙伴」怪兽加入手卡。'),
(92932860, 'Performapal Miss Director', '娱乐伙伴 诱导女导演', 'EMミス・ディレクター', 'Tuner Monster', 'Spellcaster', 'DARK', 6, NULL, 2000, '这个卡名的③的效果1回合只能使用1次。 ①：只要自己场上有「异色眼」怪兽存在，对方不能选择这张卡作为攻击对象。 ②：只要这张卡在怪兽区域守备表示存在，自己的「异色眼」怪兽不会被战斗破坏，那次战斗发生的对自己的战斗伤害变成0。 ③：以自己墓地1只1星怪兽为对象才能发动。那只怪兽效果无效特殊召唤，只用那只怪兽和这张卡为素材作同调召唤。'),
(20281581, 'Performapal Momoncarpet', '娱乐伙伴 飞毯鼯鼠', 'EMモモンカーペット', 'Pendulum Flip Effect Monster', 'Beast', 'EARTH', 3, 1000, 100, '①：这张卡反转的场合，以场上盖放的1张卡为对象才能发动。那张卡破坏。 ②：这张卡特殊召唤成功的场合才能发动。这张卡变成里侧守备表示。'),
(17330916, 'Performapal Monkeyboard', '娱乐伙伴 琴键猴', 'EMモンキーボード', 'Pendulum Effect Monster', 'Beast', 'EARTH', 6, 1000, 2400, '①：把这张卡从手卡丢弃才能发动。手卡1只「娱乐伙伴」怪兽或「异色眼」怪兽给对方观看。这个回合，那只怪兽以及自己手卡的同名怪兽的等级下降1星。'),
(56677752, 'Performapal Odd-Eyes Butler', '娱乐伙伴 异色眼管家', 'EMオッドアイズ・バトラー', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 5, 1000, 2100, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以「娱乐伙伴 异色眼管家」以外的自己场上1张「娱乐伙伴」怪兽卡或者「异色眼」怪兽卡为对象才能发动。这张卡特殊召唤。那之后，作为对象的卡破坏。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(46136942, 'Performapal Odd-Eyes Dissolver', '娱乐伙伴 异色眼溶解者', 'EMオッドアイズ・ディゾルヴァー', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 8, 2000, 2600, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：自己的灵摆怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。这张卡从手卡特殊召唤，那只自己怪兽不会被那次战斗破坏。 ②：自己主要阶段才能发动。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，自己的灵摆区域存在的融合素材怪兽也能作为融合素材使用。'),
(59762399, 'Performapal Odd-Eyes Light Phoenix', '娱乐伙伴 异色眼光凤凰', 'EMオッドアイズ・ライトフェニックス', 'Pendulum Effect Monster', 'Winged Beast', 'LIGHT', 5, 2000, 1000, '①：把这张卡解放，以自己场上1只「娱乐伙伴」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。这个效果在对方回合也能发动。'),
(65029288, 'Performapal Odd-Eyes Metal Claw', '娱乐伙伴 异色眼钢爪', 'EMオッドアイズ・メタル・クロウ', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 3000, '「异色眼」怪兽＋「娱乐伙伴」怪兽 这张卡不能作为融合素材。 ①：「融合」的效果融合召唤的这张卡不受其他卡的效果影响。 ②：这张卡的攻击宣言时发动。自己场上的全部怪兽的攻击力直到战斗阶段结束时上升300。'),
(10731333, 'Performapal Odd-Eyes Minitaurus', '娱乐伙伴 异色眼牛头人', 'EMオッドアイズ・ミノタウロス', 'Pendulum Effect Monster', 'Beast-Warrior', 'DARK', 4, 1200, 1600, '①：自己的灵摆怪兽向对方怪兽攻击的伤害计算时才能发动。那只对方怪兽的攻击力只在那次伤害计算时下降自己场上的「娱乐伙伴」卡以及「异色眼」卡数量×100。'),
(4836680, 'Performapal Odd-Eyes Seer', '娱乐伙伴 异色眼祭司', 'EMオッドアイズ・プリースト', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 6, 100, 1800, '这个卡名的怪兽效果1回合只能使用1次。 ①：灵摆召唤的这张卡在自己主要阶段可以把表示形式的以下效果发动。 ●攻击表示：把这张卡除外，以自己墓地1只「娱乐伙伴」怪兽或者「异色眼」怪兽为对象才能发动。那只怪兽特殊召唤。 ●守备表示：从卡组选1只「娱乐伙伴」灵摆怪兽或者「异色眼」灵摆怪兽表侧表示加入自己的额外卡组或送去墓地。'),
(82224646, 'Performapal Odd-Eyes Synchron', '娱乐伙伴 异色眼同步士', 'EMオッドアイズ・シンクロン', 'Pendulum Tuner Effect Monster', 'Spellcaster', 'DARK', 2, 200, 600, '从额外卡组特殊召唤的这张卡被同调召唤使用的场合除外。 ①：这张卡召唤成功时，以自己墓地的3星以下的1只「娱乐伙伴」怪兽或者「异色眼」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：1回合1次，以自己的灵摆区域1张卡为对象才能发动。那张卡效果无效特殊召唤，只用那张卡和这张卡为素材把1只同调怪兽同调召唤。'),
(86157908, 'Performapal Odd-Eyes Unicorn', '娱乐伙伴 异色眼独角兽', 'EMオッドアイズ・ユニコーン', 'Pendulum Effect Monster', 'Beast', 'LIGHT', 1, 100, 600, '①：这张卡召唤·特殊召唤成功时，以自己墓地1只「娱乐伙伴」怪兽为对象才能发动。自己回复那只怪兽的攻击力数值的基本分。'),
(82661461, 'Performapal Odd-Eyes Valet', '娱乐伙伴 异色眼仆从', 'EMオッドアイズ・バレット', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 1, 100, 200, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「娱乐伙伴 异色眼贴身男仆」以外的1只「娱乐伙伴」怪兽或者「异色眼」怪兽送去墓地。这张卡的等级直到回合结束时变成和送去墓地的怪兽的等级相同。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(56675280, 'Performapal Parrotrio', '娱乐伙伴 合唱鹦鹉', 'EMインコーラス', 'Pendulum Effect Monster', 'Winged Beast', 'WIND', 3, 500, 500, '①：这张卡被战斗破坏时才能发动。从卡组把灵摆怪兽以外的1只「娱乐伙伴」怪兽特殊召唤。'),
(69211541, 'Performapal Partnaga', '娱乐伙伴 搭档蛇', 'EMパートナーガ', 'Pendulum Effect Monster', 'Reptile', 'EARTH', 5, 500, 2100, '①：这张卡召唤·特殊召唤成功的场合，以自己场上1只怪兽为对象才能发动。那只怪兽的攻击力上升自己场上的「娱乐伙伴」怪兽数量×300。 ②：只要这张卡在怪兽区域存在，5星以下的怪兽不能攻击。'),
(47075569, 'Performapal Pendulum Sorcerer', '娱乐伙伴 灵摆魔术士', 'EMペンデュラム・マジシャン', 'Pendulum Effect Monster', 'Spellcaster', 'EARTH', 4, 1500, 800, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，以自己场上最多2张卡为对象才能发动。那些卡破坏，把破坏数量的「娱乐伙伴 灵摆魔术家」以外的「娱乐伙伴」怪兽从卡组加入手卡（同名卡最多1张）。'),
(36415522, 'Performapal Pinch Helper', '娱乐伙伴危机帮手', 'EMピンチヘルパー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，对方怪兽的直接攻击宣言时才能把这个效果发动。那次攻击无效，从卡组把1只「娱乐伙伴」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：自己怪兽和对方怪兽进行战斗的攻击宣言时，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(11481610, 'Performapal Popperup', '娱乐伙伴弹出', 'EMポップアップ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把最多3张手卡送去墓地才能发动。自己从卡组抽出那个数量。那之后，可以把最多有这个效果抽出的数量的持有用自己的灵摆区域2张卡的灵摆刻度可以灵摆召唤的等级的「娱乐伙伴」怪兽、「魔术师」灵摆怪兽、「异色眼」怪兽从手卡特殊召唤（同名卡最多1张）。没因这张卡的效果特殊召唤的场合，自己失去自己手卡数量×1000基本分。'),
(71863024, 'Performapal Radish Horse', '娱乐伙伴 萝卜马', 'EMラディッシュ・ホース', 'Pendulum Effect Monster', 'Plant', 'EARTH', 4, 500, 2000, '①：特殊召唤的怪兽在对方场上存在，对方场上的怪兽数量是自己场上的怪兽数量以上的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，以对方场上1只表侧表示怪兽和自己场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只对方怪兽的攻击力下降这张卡的攻击力数值，那只自己怪兽的攻击力上升这张卡的攻击力数值。'),
(16617334, 'Performapal Rain Goat', '娱乐伙伴 雨衣山羊', 'EMレインゴート', 'Effect Monster', 'Beast', 'WATER', 1, NULL, NULL, '①：给与自己伤害的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个效果让自己受到的伤害变成0。 ②：自己·对方的主要阶段把这张卡从手卡丢弃，以自己场上1张「娱乐伙伴」卡或者「异色眼」卡为对象才能发动。这个回合，那张卡不会被战斗·效果破坏。'),
(71705144, 'Performapal Recasting', '娱乐伙伴阵容更换', 'EMキャスト・チェンジ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「娱乐伙伴阵容更换」在1回合只能发动1张。 ①：把手卡的「娱乐伙伴」怪兽任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量＋1张。'),
(5672432, 'Performapal Revival', '娱乐伙伴复活', 'EMリバイバル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽被战斗·效果破坏的场合才能发动。从自己的手卡·墓地选1只「娱乐伙伴」怪兽特殊召唤。'),
(36527535, 'Performapal Revue Dancer', '娱乐伙伴 时事秀舞者', 'EMレビュー・ダンサー', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 800, 1000, '①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：「娱乐伙伴」怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(44364077, 'Performapal Salutiger', '娱乐伙伴 士兵虎', 'EMヘイタイガー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1700, 500, '「娱乐伙伴 士兵虎」的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只「娱乐伙伴」灵摆怪兽加入手卡。'),
(33833230, 'Performapal Seal Eel', '娱乐伙伴 封条鳗', 'EMシール・イール', 'Pendulum Effect Monster', 'Fish', 'WATER', 1, 100, 100, '①：这张卡召唤·特殊召唤成功时，以对方场上盖放的1张魔法·陷阱卡为对象才能发动。这个回合，那张卡不能发动。双方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。'),
(15978426, 'Performapal Secondonkey', '娱乐伙伴 副手驴', 'EMセカンドンキー', 'Effect Monster', 'Beast', 'EARTH', 4, 1000, 2000, '①：这张卡召唤·特殊召唤成功时才能发动。从卡组把「娱乐伙伴 副手驴」以外的1只「娱乐伙伴」怪兽送去墓地。自己的灵摆区域有2张卡存在的场合，也能不送去墓地加入手卡。'),
(23377694, 'Performapal Sellshell Crab', '娱乐伙伴 房东寄居蟹', 'EMオオヤヤドカリ', 'Pendulum Effect Monster', 'Aqua', 'WATER', 5, 500, 2500, '①：1回合1次，以自己场上1只灵摆怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升自己场上的「娱乐伙伴」怪兽数量×300。'),
(92958307, 'Performapal Show Down', '娱乐伙伴表演尾声', 'EMショーダウン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以最多有自己场上的表侧表示的魔法卡数量的对方场上的表侧表示怪兽为对象才能发动。那些怪兽变成里侧守备表示。'),
(26270847, 'Performapal Silver Claw', '娱乐伙伴 银爪狼', 'EMシルバー・クロウ', 'Pendulum Effect Monster', 'Beast', 'DARK', 4, 1800, 800, '①：这张卡的攻击宣言时发动。自己场上的「娱乐伙伴」怪兽的攻击力直到战斗阶段结束时上升300。'),
(42562690, 'Performapal Skeeter Skimmer', '娱乐伙伴 小艇水黾', 'EMアメンボート', 'Effect Monster', 'Insect', 'WATER', 4, 500, 1600, '①：攻击表示的这张卡被选择作为攻击对象时才能发动。这张卡变成表侧守备表示，那次攻击无效。'),
(40318957, 'Performapal Skullcrobat Joker', '娱乐伙伴 骷髅杂技小丑', 'EMドクロバット・ジョーカー', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 100, '①：这张卡召唤时才能发动。「娱乐伙伴 骷髅杂技小丑」以外的「娱乐伙伴」怪兽、「魔术师」灵摆怪兽、「异色眼」怪兽之内任意1只从卡组加入手卡。'),
(73734821, 'Performapal Sky Magician', '娱乐伙伴 天空魔术家', 'EMスカイ・マジシャン', 'Effect Monster', 'Spellcaster', 'WIND', 7, 2500, 2000, '「娱乐伙伴 天空魔术家」的②的效果1回合只能使用1次。 ①：1回合1次，自己把魔法卡发动的场合发动。这张卡的攻击力上升300。 ②：以自己场上1张永续魔法卡为对象才能发动。那张卡回到持有者手卡。那之后，可以从手卡把1张「魔术师」永续魔法卡发动。这个效果在对方回合也能发动。 ③：表侧表示的这张卡从场上离开的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(3859859, 'Performapal Sky Magician Girl', '娱乐伙伴 天空魔术少女', 'EMスカイ・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'WIND', 5, 2000, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有永续魔法卡存在的场合才能发动。这张卡特殊召唤。 ②：这张卡从手卡特殊召唤的场合才能发动。从卡组把1只4星以下的魔法师族·光属性怪兽送去墓地。 ③：表侧表示的这张卡从场上离开的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(122520, 'Performapal Sky Pupil', '娱乐伙伴 天空徒弟', 'EMスカイ・ピューピル', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 800, 800, '「娱乐伙伴 天空徒弟」的①的效果1回合只能使用1次。 ①：让自己场上1只5星以上的「娱乐伙伴」怪兽回到持有者手卡才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：这张卡和对方怪兽进行战斗的场合，直到伤害步骤结束时那只怪兽的效果无效化。 ③：自己场上有其他的「娱乐伙伴」怪兽存在的场合，这张卡向对方怪兽攻击的伤害计算前才能发动。那只对方怪兽破坏。'),
(20403123, 'Performapal Sleight Hand Magician', '娱乐伙伴 手艺魔术家', 'EMスライハンド・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 7, 2500, 2000, '①：这张卡可以把灵摆怪兽以外的自己场上1只「娱乐伙伴」怪兽解放从手卡特殊召唤。 ②：1回合1次，丢弃1张手卡，以场上1张表侧表示的卡为对象才能发动。那张卡破坏。'),
(7799906, 'Performapal Smile Sorcerer', '娱乐伙伴 笑容魔术家', 'EMスマイル・マジシャン', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「笑容」魔法·陷阱卡加入手卡。 ②：自己场上的怪兽只有「娱乐伙伴」怪兽、「魔术师」灵摆怪兽、「异色眼」怪兽，这张卡的攻击力比原本攻击力高的场合才能发动。自己从卡组抽出持有比原本攻击力高的攻击力的自己场上的怪兽的数量。这个回合，自己不能把怪兽特殊召唤。'),
(22091345, 'Performapal Spikeagle', '娱乐伙伴 尖刺鹰', 'EMスパイク・イーグル', 'Effect Monster', 'Winged Beast', 'WIND', 2, 900, 900, '①：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(52963531, 'Performapal Splashmammoth', '娱乐伙伴 洒水猛犸', 'EMマンモスプラッシュ', 'Pendulum Effect Monster', 'Beast', 'WATER', 6, 1900, 2300, '「娱乐伙伴 洒水猛犸」的怪兽效果在决斗中只能使用1次。 ①：自己主要阶段才能发动。从自己场上把龙族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(128454, 'Performapal Springoose', '娱乐伙伴 弹簧鹅', 'EMスプリングース', 'Effect Monster', 'Winged Beast', 'WIND', 5, 1100, 2400, '「娱乐伙伴 弹簧鹅」的效果1回合只能使用1次。 ①：自己主要阶段把墓地的这张卡除外，从自己的灵摆区域的「魔术师」卡、「娱乐伙伴」卡以及自己场上的灵摆怪兽之中以2张为对象才能发动。那2张卡回到持有者手卡。'),
(65195959, 'Performapal Stamp Turtle', '娱乐伙伴 加号龟', 'EMプラスタートル', 'Effect Monster', 'Aqua', 'WATER', 4, 100, 1800, '①：1回合1次，以场上最多2只表侧表示怪兽为对象才能发动。那些怪兽的等级上升1星。'),
(93892436, 'Performapal Swincobra', '娱乐伙伴 秋千眼镜蛇', 'EMブランコブラ', 'Pendulum Effect Monster', 'Reptile', 'EARTH', 4, 300, 1800, '①：这张卡可以直接攻击。 ②：这张卡攻击的场合，战斗阶段结束时变成守备表示。'),
(15452043, 'Performapal Sword Fish', '娱乐伙伴 宝剑鱼', 'EMソード・フィッシュ', 'Effect Monster', 'Fish', 'WATER', 2, 600, 600, '①：这张卡召唤·特殊召唤成功的场合发动。对方场上的全部怪兽的攻击力·守备力下降600。 ②：这张卡在怪兽区域存在，自己对怪兽的特殊召唤成功的场合发动。对方场上的全部怪兽的攻击力·守备力下降600。'),
(29169993, 'Performapal Teeter Totter Hopper', '娱乐伙伴 跷跷板蝗虫', 'EMギッタンバッタ', 'Effect Monster', 'Insect', 'EARTH', 4, 100, 1200, '「娱乐伙伴 跷跷板蝗虫」的③的效果1回合只能使用1次。 ①：特殊召唤的这张卡1回合只有1次不会被战斗破坏。 ②：对方结束阶段以自己墓地1只3星以下的「娱乐伙伴」怪兽为对象才能发动。这张卡送去墓地，那只怪兽加入手卡。 ③：这张卡在墓地存在的状态，「娱乐伙伴」怪兽从手卡送去自己墓地的场合才能发动。这张卡从墓地特殊召唤。'),
(70458081, 'Performapal Thunderhino', '娱乐伙伴 迅雷犀牛', 'EMジンライノ', 'Effect Monster', 'Rock', 'LIGHT', 3, 200, 1800, '①：只要这张卡在怪兽区域存在，对方不能选择其他的「娱乐伙伴」怪兽作为攻击对象。 ②：这张卡在墓地存在，「娱乐伙伴 迅雷犀牛」以外的自己场上的「娱乐伙伴」卡被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(43241495, 'Performapal Trampolynx', '娱乐伙伴 蹦床猞猁', 'EMトランポリンクス', 'Pendulum Effect Monster', 'Beast', 'EARTH', 2, 300, 300, '①：这张卡召唤成功时，以自己或者对方的灵摆区域1张卡为对象才能发动。那张卡回到持有者手卡。'),
(42002073, 'Performapal Trump Girl', '娱乐伙伴 扑克少女', 'EMトランプ・ガール', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 2, 200, 200, '①：1回合1次，自己主要阶段才能发动。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：这张卡在灵摆区域被破坏的场合，以自己墓地1只龙族融合怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(91584698, 'Performapal Trump Witch', '娱乐伙伴 扑克魔女', 'EMトランプ・ウィッチ', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 1, 100, 100, '①：把这张卡解放才能发动。从自己的卡组·墓地选1张「融合」加入手卡。'),
(32787239, 'Performapal Trumpanda', '娱乐伙伴 喇叭熊猫', 'EMラ・パンダ', 'Pendulum Effect Monster', 'Beast', 'EARTH', 3, 800, 800, '「娱乐伙伴 喇叭熊猫」的怪兽效果1回合只能使用1次。 ①：自己的灵摆怪兽被选择作为攻击对象时才能发动。那次攻击无效。'),
(4239451, 'Performapal Turn Toad', '娱乐伙伴 颠倒蛙', 'EMヒックリカエル', 'Pendulum Effect Monster', 'Aqua', 'WATER', 2, NULL, 800, '①：自己战斗阶段1次，以自己场上1只怪兽为对象才能发动。那只怪兽的表示形式变更，那个攻击力·守备力直到回合结束时交换。'),
(220414, 'Performapal Turn Trooper', '娱乐伙伴 掉头跑骑兵', 'EMターントルーパー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1200, 1200, '①：自己战斗阶段开始时才能发动。给这张卡放置1个指示物（最多2个）。 ②：这张卡得到这张卡的指示物数量的以下效果。 ●1个：1回合1次，对方怪兽的攻击宣言时才能发动。那次攻击无效。 ●2个：把这张卡解放才能发动。直到发动后第2次的对方结束阶段，场上的怪兽全部除外。'),
(73511233, 'Performapal U Go Golem', '娱乐伙伴 U合石人', 'EMユーゴーレム', 'Pendulum Effect Monster', 'Fiend', 'DARK', 4, 1600, 1000, '①：这张卡灵摆召唤成功的回合的自己主要阶段才能发动1次。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。那个时候，其他的融合素材怪兽必须全部是龙族怪兽。'),
(7714344, 'Performapal Uni', '娱乐伙伴 小独', 'EMユニ', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 800, 1500, '①：这张卡召唤·特殊召唤成功的回合的自己主要阶段才能发动1次。从手卡把1只3星以下的「娱乐伙伴」怪兽攻击表示特殊召唤。 ②：对方回合，从自己墓地把这张卡和1只「娱乐伙伴 小独」以外的「娱乐伙伴」怪兽除外才能发动。这个回合自己受到的战斗伤害只有1次变成0。'),
(64450427, 'Performapal Whim Witch', '娱乐伙伴 妙想魔女', 'EMウィム・ウィッチ', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 3, 800, 800, '①：灵摆怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(79967395, 'Performapal Whip Snake', '娱乐伙伴 鞭子蛇', 'EMウィップ・バイパー', 'Effect Monster', 'Reptile', 'EARTH', 4, 1700, 900, '①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时交换。这个效果在双方的主要阶段才能发动。'),
(72924435, 'Periallis, Empress of Blossoms', '璎珞帝华－冠花贝母', '瓔珞帝華－ペリアリス', 'Synchro Monster', 'Plant', 'LIGHT', 7, 1600, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升自己场上的其他的植物族怪兽数量×400。 ②：自己主要阶段才能发动。除「璎珞帝华-帝王贝母」外的1只5星以上的植物族怪兽从自己的手卡·墓地守备表示特殊召唤。'),
(69764158, 'Peropero Cerperus', '舔舔三头犬', 'ペロペロケルペロス', 'Effect Monster', 'Beast', 'EARTH', 3, NULL, 1800, '①：这张卡在墓地存在，战斗或者对方的效果让自己受到伤害的场合，把墓地的这张卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(53936268, 'Personal Spoofing', '个人欺骗', 'パーソナル・スプーフィング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，从手卡以及自己场上的表侧表示的卡之中让1张「幻变骚灵」卡回到持有者卡组才能发动。从卡组把1只「幻变骚灵」怪兽加入手卡。'),
(66429798, 'Pesanta the Troubadour Deity', '吟幽狮神 佩桑塔', '吟幽獅神ペサンタ', 'Normal Monster', 'Illusion', 'DARK', 8, 2500, 2500, '因应虔敬的祈祷而显现的异形。据说是吟咏着未来预言之诗，但是其内容太不可思议完全无法理解。'),
(62472614, 'Pestilence', '疫病', '疫病', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族·兽战士族·魔法师族怪兽才能装备。装备怪兽的攻击力变成0。此外，每次自己的准备阶段，给与装备怪兽的控制者500分伤害。'),
(52624755, 'Peten the Dark Clown', '暗道化师 彼得', '闇・道化師のペーテン', 'Effect Monster', 'Spellcaster', 'DARK', 3, 500, 1200, '①：这张卡被送去墓地时，把墓地的这张卡除外才能发动。从手卡·卡组把1只「暗道化师 彼得」特殊召唤。'),
(38142739, 'Petit Angel', '小天使', 'プチテンシ', 'Normal Monster', 'Fairy', 'LIGHT', 3, 600, 900, '依靠灵活的行动躲避攻击的小天使。'),
(75356564, 'Petit Dragon', '小龙', 'プチリュウ', 'Normal Monster', 'Dragon', 'WIND', 2, 600, 700, '非常小的龙，充分用尽那弱小的身体进行攻击。'),
(58192742, 'Petit Moth', '飞蛾宝宝', 'プチモス', 'Normal Monster', 'Insect', 'EARTH', 1, 300, 200, '不清楚成长后会变成什么样的小幼虫。'),
(82946847, 'Petiteranodon', '小翼龙', 'プチラノドン', 'Effect Monster', 'Dinosaur', 'EARTH', 2, 500, 500, '①：这张卡被效果破坏送去墓地的场合发动。从卡组把1只4星以上的恐龙族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(59901153, 'Phalaenop Sisters', '蝴蝶姐妹', '胡蝶姉妹', 'Effect Monster', 'Fairy', 'WIND', 1, 300, 300, '这个卡名的效果1回合只能使用1次。 ①：自己场上的怪兽的等级合计是对方场上的怪兽的等级合计以下的场合，把这张卡解放才能发动。从卡组把1只7星以上的昆虫族·植物族怪兽加入手卡，这个回合中，以下效果适用。 ●只要自己对这个效果加入手卡的怪兽或者原本卡名和那只怪兽相同的怪兽的召唤·特殊召唤不成功，结束阶段让自己受到2700伤害。'),
(42709949, 'Phalanx Pike', '守护神之矛', '守護神の矛', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升双方墓地存在的和装备怪兽同名的卡数量×900的数值。'),
(95463814, 'Phantasm Emperor Trilojig', '幻魔帝特里洛吉克', '幻魔帝トリロジーグ', 'Fusion Monster', 'Fiend', 'DARK', 10, 4000, 4000, '10星怪兽×3 这个卡名的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合或者这张卡已在怪兽区域存在的状态有这张卡以外的怪兽从墓地往自己场上特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。给与对方那只怪兽的原本攻击力一半数值的伤害。'),
(97795930, 'Phantasm Spiral Assault', '幻煌龙的天涡', '幻煌龍の天渦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上有「海」存在的场合，这张卡的发动从手卡也能用。 ①：以自己场上1只「幻煌龙 螺旋」为对象才能发动。那只怪兽用有「幻煌龙」装备魔法卡3种类以上装备的状态战斗破坏对方3只效果怪兽时，自己决斗胜利。 ②：自己场上的通常怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(34302287, 'Phantasm Spiral Battle', '幻煌龙的战涡', '幻煌龍の戦渦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上有「海」存在的场合，这张卡的发动从手卡也能用。 ①：自己场上的怪兽只有通常怪兽的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：把墓地的这张卡除外，以自己场上1只通常怪兽为对象才能发动。那只怪兽可以装备的自己场上的全部「幻煌龙」装备魔法卡给那只通常怪兽装备。'),
(48308134, 'Phantasm Spiral Crash', '幻煌龙的螺旋突', '幻煌龍の螺旋突', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '通常怪兽才能装备。「幻煌龙的螺旋突」的②的效果1回合只能使用1次。 ①：装备怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：装备怪兽给与对方战斗伤害时才能发动。从自己的手卡·卡组·墓地选1只「幻煌龙 螺旋」特殊召唤，这张卡给那只怪兽装备。那之后，可以选对方场上1只攻击表示怪兽变成守备表示。'),
(56649609, 'Phantasm Spiral Dragon', '幻煌龙 螺旋', '幻煌龍 スパイラル', 'Normal Monster', 'Wyrm', 'WATER', 8, 2900, 2900, '经历了炽烈战涡的猛龙。其负伤之躯接触古老光芒，最终完成自身的浸涡。不久，巨龙展开自己的双翅，变为称霸天涡的煌者。那位新生的煌，究竟是梦是真还是幻。'),
(75702749, 'Phantasm Spiral Grip', '幻煌龙的螺旋绞', '幻煌龍の螺旋絞', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '通常怪兽才能装备。「幻煌龙的螺旋绞」的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升500。 ②：装备怪兽战斗破坏对方怪兽时才能发动。从自己的手卡·卡组·墓地选1只「幻煌龙 螺旋」特殊召唤，这张卡给那只怪兽装备。那之后，给与对方1000伤害。'),
(61397885, 'Phantasm Spiral Power', '幻煌龙的浸涡', '幻煌龍の浸渦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上有「海」存在的场合，这张卡的发动从手卡也能用。 ①：自己场上的怪兽只有通常怪兽的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽直到回合结束时攻击力·守备力下降1000，效果无效化。 ②：把墓地的这张卡除外，以自己场上1只通常怪兽为对象才能发动。从自己的手卡·墓地选1张「幻煌龙」装备魔法卡给那只通常怪兽装备。'),
(2819436, 'Phantasm Spiral Token', '幻煌之都 帕西菲斯', '幻煌の都 パシフィス', 'Token', 'Wyrm', NULL, NULL, NULL, NULL, NULL),
(1197847, 'Phantasm Spiral Wave', '幻煌龙的螺旋波', '幻煌龍の螺旋波', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '通常怪兽才能装备。「幻煌龙的螺旋波」的②的效果1回合只能使用1次。 ①：装备怪兽1回合只有1次不会被战斗破坏。 ②：装备怪兽进行战斗的战斗阶段结束时才能发动。从自己的手卡·卡组·墓地选1只「幻煌龙 螺旋」特殊召唤，这张卡给那只怪兽装备。那之后，有对方手卡的场合，对方选1张手卡丢弃。'),
(69890968, 'Phantasm Token', '幻魔皇拉比艾尔', '幻魔皇ラビエル', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(90884403, 'Phantasmal Lord Ultimitl Bishbaalkin', '究极幻神 奥特美特尔·比希巴尔金', '究極幻神 アルティミトル・ビシバールキン', 'Synchro Monster', 'Dragon', 'DARK', NULL, NULL, NULL, '规则上，这张卡的等级当作12星使用。这张卡不能同调召唤，把自己场上的8星以上而相同等级的调整和调整以外的怪兽各1只送去墓地的场合才能特殊召唤。 ①：这张卡不会被效果破坏，攻击力上升场上的怪兽数量×1000。 ②：1回合1次，自己·对方的主要阶段才能发动。在双方场上把相同数量的「邪眼神衍生物」（恶魔族·暗·1星·攻/守0）尽可能守备表示特殊召唤。这个回合这张卡不能攻击。'),
(93224849, 'Phantasmal Martyr Token', '幻魔殉教者', '幻魔の殉教者', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(93224848, 'Phantasmal Martyrs', '幻魔殉教者', '幻魔の殉教者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡以外的自己手卡有2张以上存在，自己场上有「神炎皇 乌利亚」或者「降雷皇 哈蒙」存在的场合，把手卡全部送去墓地才能发动。在自己场上把3只「幻魔的殉教者衍生物」（恶魔族·暗·1星·攻/守0）攻击表示特殊召唤。'),
(53134520, 'Phantasmal Summoning Beast', '幻魔召唤神', '幻魔の召喚神', 'Effect Monster', 'Fiend', 'DARK', 7, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只从自己的卡组·墓地加入手卡。那之后，可以把攻击力和守备力的数值相同的1只炎族·雷族·恶魔族的10星怪兽从手卡无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在这个回合不能直接攻击。 ②：把墓地的这张卡除外才能发动。从卡组把1张「次元融合杀」加入手卡。'),
(99792080, 'Phantasos, the Dream Mirror Foe', '梦魔镜魔兽－幻塔斯', '夢魔鏡の魔獣－パンタス', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1900, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合才能发动。这个回合，这张卡可以直接攻击。 ②：场地区域有「圣光之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的圣兽-方塔斯」特殊召唤。'),
(62393472, 'Phantasos, the Dream Mirror Friend', '梦魔镜圣兽－幻塔斯', '夢魔鏡の聖獣－パンタス', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 900, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合，以「梦魔镜的圣兽-方塔斯」以外的自己墓地1只8星以下的「梦魔镜」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：场地区域有「黯黑之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的魔兽-方塔斯」特殊召唤。'),
(71181155, 'Phantom Beast Cross-Wing', '幻兽 十字翼鸟', '幻獣クロスウィング', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1300, 1300, '只要这张卡在墓地存在，场上的名字带有「幻兽」的怪兽的攻击力上升300。'),
(70969517, 'Phantom Beast Rock-Lizard', '幻兽 巨岩蜥', '幻獣ロックリザード', 'Effect Monster', 'Beast-Warrior', 'DARK', 7, 2200, 2000, '把名字带有「幻兽」的怪兽作为祭品的场合，这张卡可以用1只祭品作召唤。这张卡每战斗破坏1只怪兽，给与对方基本分500分伤害。对方控制的卡效果把这张卡破坏送去墓地时，给与对方基本分2000分伤害。'),
(34961968, 'Phantom Beast Thunder-Pegasus', '幻兽 雷霆飞马', '幻獣サンダーペガス', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 700, 2000, '对方怪兽的攻击宣言时，把墓地的这张卡从游戏中除外，选择自己场上1只名字带有「幻兽」的怪兽才能发动。这个回合，选择的自己怪兽不会被战斗破坏。'),
(7576264, 'Phantom Beast Wild-Horn', '幻兽 野角驼鹿', '幻獣ワイルドホーン', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1700, NULL, '这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(17189532, 'Phantom Bounzer', '幻影保镖', 'ファントム・バウンサー', 'Effect Monster', 'Warrior', 'DARK', 6, 2400, 1200, '场上的这张卡被破坏送去墓地的场合，可以从卡组把2张名字带有「保镖」的卡加入手卡。'),
(56605802, 'Phantom Cricket', '幻影蟋蟀', '幻影コオロギ', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 300, 1000, '反转：场上里侧表示存在的1只怪兽回到持有者卡组最上面。'),
(77603950, 'Phantom Dewan', '萨塔那', 'サターナ', 'Normal Monster', 'Spellcaster', 'DARK', 2, 700, 600, '诅咒敌人。可以使人动弹不得的魔法师。'),
(49879995, 'Phantom Dragon', '幻龙', 'ファントム・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2300, 2200, '对方把怪兽特殊召唤成功时，可以从手卡把这张卡特殊召唤。只要这张卡在场上表侧表示存在，自己的怪兽卡区域2处变成不能使用。'),
(43191636, 'Phantom Dragonray Bronto', '龙影鱼 雷龙鳐', '竜影魚レイ・ブロント', 'Gemini Monster', 'Fish', 'WATER', 4, 1500, 1000, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡的原本攻击力变成2300。这张卡攻击的场合，战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡不能把表示形式改变。'),
(95113856, 'Phantom Fortress Enterblathnir', '幻子力航母 神舟进取号', '幻子力空母エンタープラズニル', 'XYZ Monster', 'Machine', 'WIND', 9, 2900, 2500, '9星怪兽×2 ①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●选对方场上1张卡除外。 ●对方手卡随机选1张除外。 ●选对方墓地1张卡除外。 ●对方卡组最上面的卡除外。'),
(61201220, 'Phantom Ghost', '幽灵', 'ゴースト', 'Normal Monster', 'Zombie', 'DARK', 2, 600, 800, '由这个世界上不能成佛的灵魂，慢慢聚集而成的怨灵。'),
(74852097, 'Phantom Gryphon', '幻之狮鹫', '幻のグリフォン', 'Normal Monster', 'Winged Beast', 'WIND', 4, 2000, NULL, '隐居于山岳的传说中怪兽。据说它的双翼振翅一下就会掀起风暴。好像跟鹰身女妖的关系很差，围绕着狩猎场不断发生纷争。'),
(40555959, 'Phantom Hand', '空手假象', 'ハンドレス・フェイク', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「永火」的怪兽表侧表示存在的场合，1回合只有1次，可以直到下次的自己的准备阶段时把自己手卡全部里侧表示从游戏中除外。'),
(6901008, 'Phantom King Hydride', '幻影王 氢骑', '幻影王 ハイド・ライド', 'Tuner Monster', 'Fiend', 'DARK', 3, 1500, 300, '①：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(25542642, 'Phantom Knights'' Fog Blade', '魅影雾剑', '幻影霧剣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只效果怪兽为对象才能把这张卡发动。这个卡名的②的效果1回合只能使用1次。 ①：作为对象的怪兽不能攻击，效果无效化，双方怪兽不能选择作为对象的怪兽作为攻击对象。那只怪兽从场上离开时这张卡破坏。 ②：把墓地的这张卡除外，以自己墓地1只「幻影骑士团」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(88504133, 'Phantom Knights'' Rank-Up-Magic Force', '升阶魔法－魅影之力', 'RUM－ファントム・フォース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，从自己墓地把暗属性怪兽任意数量除外，以自己场上1只暗属性超量怪兽为对象才能发动。比作为对象的自己怪兽阶级要高除外数量数值的「幻影骑士团」、「急袭猛禽」、「超量龙」超量怪兽之内任意1只在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这张卡的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。'),
(98153934, 'Phantom Knights'' Spear', '幻影死枪', '幻影死槍', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次以自己场上的「幻影骑士团」怪兽为对象的对方的效果发动给与对方500伤害。 ②：自己场上的暗属性怪兽被战斗或者对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(61936647, 'Phantom Knights'' Sword', '魅影剑', '幻影剣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只表侧表示怪兽为对象才能把这张卡发动。「幻影剑」的②的效果1回合只能使用1次。 ①：作为对象的怪兽的攻击力上升800，被战斗·效果破坏的场合，可以作为代替把这张卡破坏。那只怪兽从场上离开时这张卡破坏。 ②：把墓地的这张卡除外，以自己墓地1只「幻影骑士团」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(98431356, 'Phantom Knights'' Wing', '魅影翼', '幻影翼', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「幻影翼」的②的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升500，这个回合只有1次不会被战斗·效果破坏。 ②：把墓地的这张卡除外，以自己墓地1只「幻影骑士团」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(24103628, 'Phantom Magician', '幻影魔术士', '幻影の魔術士', 'Effect Monster', 'Spellcaster', 'DARK', 3, 600, 700, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只攻击力1000以下的名字带有「英雄」的怪兽表侧守备表示特殊召唤。'),
(30312361, 'Phantom of Chaos', '混沌魅影', 'ファントム・オブ・カオス', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, NULL, '①：1回合1次，以自己墓地1只效果怪兽为对象才能发动。那只怪兽除外，这张卡直到结束阶段当作和那只怪兽同名卡使用，得到相同的原本攻击力和效果。 ②：这张卡的战斗发生的对对方的战斗伤害变成0。'),
(80453041, 'Phantom of Yubel', '尤贝尔的魅影', 'ファントム・オブ・ユベル', 'Fusion Monster', 'Fiend', 'DARK', 9, NULL, NULL, '「于贝尔」怪兽＋攻击力和守备力是0的恶魔族怪兽 让自己的手卡·场上·墓地的上记的卡回到卡组·额外卡组的场合才能特殊召唤。这张卡不能作为融合素材。这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：对方怪兽的效果发动时，把这张卡解放才能发动。那个效果变成「对方把自身的手卡·卡组·场上1只「于贝尔」怪兽破坏」。'),
(12958919, 'Phantom Skyblaster', '幻铳士', '幻銃士', 'Effect Monster', 'Fiend', 'DARK', 4, 1100, 800, '①：这张卡召唤·反转召唤成功时才能发动。把最多有自己场上的怪兽数量的「铳士衍生物」（恶魔族·暗·4星·攻/守500）在自己场上特殊召唤。 ②：自己准备阶段才能发动。给与对方为自己场上的「铳士」怪兽数量×300伤害。这个效果发动的回合，自己的「铳士」怪兽不能攻击宣言。'),
(1426715, 'Phantom Token', '编号48 暗影巫妖', 'No.48 シャドー・リッチ', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(52550973, 'Pharaoh''s Servant', '法老的仆人', 'ファラオのしもべ', 'Normal Monster', 'Zombie', 'DARK', 2, 900, NULL, '据域是曾经侍奉过法老的人们的亡灵。拥有丝毫不会动摇的忠诚之心。'),
(63571750, 'Pharaoh''s Treasure', '王家的财宝', '王家の財宝', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后，这张卡表面向上混到自己的卡组。抽回那张卡的时候送到墓地，从自己的墓地选择这张卡以外的1张其他的卡加入手卡。'),
(23099524, 'Pharaonic Advent', '法老降临', 'ファラオニック・アドベント', 'Effect Monster', 'Spellcaster', 'DARK', 8, 2000, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：把自己场上1只怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力上升双方的场上·墓地的永续陷阱卡数量×300。 ③：把自己场上1只天使族·恶魔族·爬虫类族怪兽解放才能发动。从卡组把1张永续陷阱卡加入手卡。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。'),
(89707961, 'Pharaonic Guardian Sphinx', '王家的守护者 斯芬克斯', '王家の守護者スフィンクス', 'Effect Monster', 'Rock', 'EARTH', 8, 2300, 3000, '这个卡名的②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转召唤成功的场合发动。对方场上的怪兽全部回到持有者卡组。 ③：场上的这张卡被对方破坏的场合才能发动。从手卡·卡组把1只岩石族·5星怪兽里侧守备表示特殊召唤。'),
(89959682, 'Pharaonic Protector', '王家的守护者', '王家の守護者', 'Normal Monster', 'Zombie', 'EARTH', 2, 900, NULL, '守护王家几千年的兵士的木乃伊。其灵魂现在也决不饶恕任何入侵者。'),
(43791861, 'Phoenix Beast Gairuda', '凤王兽 铠楼罗', '鳳王獣ガイルーダ', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2500, 1200, '这张卡向对方怪兽攻击的场合，伤害步骤内攻击力上升300。'),
(33872334, 'Phoenix Gearblade', '不死鸟・机亚锋烈刀', 'フェニックス・ギア・ブレード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽或炎属性怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升300。 ②：装备怪兽攻击的伤害步骤结束时，把这张卡送去墓地才能发动。这次战斗阶段中，自己的战士族怪兽以及炎属性怪兽各可以作2次攻击。 ③：这张卡为让怪兽的效果发动，被送去墓地的场合或者被除外的场合才能发动。这张卡加入手卡。'),
(69488544, 'Phoenix Gearfried', '不死鸟・机亚弗里德', 'フェニックス・ギア・フリード', 'Gemini Monster', 'Warrior', 'FIRE', 8, 2800, 2200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●对方把魔法卡发动的场合，以自己墓地1只二重怪兽为对象才能发动。那只怪兽特殊召唤。 ●场上的怪兽为对象的魔法·陷阱卡发动时，把自己场上1张表侧表示的装备卡送去墓地才能发动。那个发动无效并破坏。'),
(63356631, 'Phoenix Wing Wind Blast', '凤翼爆风', '鳳翼の爆風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以对方场上1张卡为对象才能发动。那张对方的卡回到持有者卡组最上面。'),
(23558733, 'Phoenixian Cluster Amaryllis', '凤凰石蒜花', 'フェニキシアン・クラスター・アマリリス', 'Effect Monster', 'Plant', 'FIRE', 8, 2200, NULL, '这张卡不用「凤凰花种」或者这张卡的效果不能特殊召唤。这张卡攻击的场合，伤害计算后破坏。自己场上存在的这张卡被破坏送去墓地时，给与对方基本分800分伤害。自己的结束阶段时这张卡在墓地存在的场合，可以把自己墓地存在的1只植物族怪兽从游戏中除外，这张卡从墓地守备表示特殊召唤。'),
(96553688, 'Phoenixian Seed', '凤凰花种', 'フェニキシアン・シード', 'Effect Monster', 'Plant', 'FIRE', 2, 800, NULL, '把自己场上表侧表示存在的这张卡送去墓地发动。从自己手卡把1只「凤凰石蒜花」特殊召唤。'),
(67556500, 'Phonon Pulse Dragon', '波动龙 声子龙', '波動竜フォノン・ドラゴン', 'Synchro Tuner Monster', 'Dragon', 'DARK', 4, 1900, 800, '调整＋调整以外的怪兽1只以上 这张卡同调召唤成功时，宣言1～3的等级才能发动。这张卡的等级变成宣言的等级。这个效果发动过的回合，自己不能作以这张卡为同调素材的同调召唤以外的特殊召唤。自己对「波动龙 声子龙」1回合只能有1次特殊召唤。'),
(8192327, 'Phosphorage the Elemental Lord', '光灵神 福斯奥拉热', '光霊神フォスオラージュ', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的光属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功时才能发动。对方场上的怪兽全部破坏。 ②：表侧表示的这张卡从场上离开的场合，下次的自己回合的战斗阶段跳过。'),
(98881931, 'Photon Advancer', '光子前行者', 'フォトン・アドバンサー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1000, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：场上有「光子」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上有这张卡以外的「光子」怪兽存在的场合，这张卡的攻击力上升1000。'),
(75797046, 'Photon Alexandra Queen', '光子亚历山大蝶后', 'フォトン・アレキサンドラ・クィーン', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2400, 1200, '名字带有「幻蝶刺客」的4星怪兽×2 把这张卡1个超量素材取除才能发动。场上的怪兽全部回到持有者手卡。那之后，这个效果让卡加入手卡的玩家受到那个数量×300的数值的伤害。'),
(71233859, 'Photon Booster', '光子推进', 'フォトン・ブースター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择衍生物以外的场上表侧表示存在的1只4星以下的光属性怪兽发动。选择的怪兽以及场上表侧表示存在的同名的怪兽的攻击力直到结束阶段时变成2000。'),
(13492423, 'Photon Caesar', '光子凯撒', 'フォトン・カイザー', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2000, 2800, '这张卡召唤·反转召唤成功时，可以从自己的手卡·卡组把1只「光子帝王」特殊召唤。'),
(28990150, 'Photon Cerberus', '光子三头犬', 'フォトン・ケルベロス', 'Effect Monster', 'Beast', 'LIGHT', 3, 1300, 600, '这张卡召唤成功的回合，只要这张卡在场上表侧表示存在双方不能把陷阱卡发动。'),
(42925441, 'Photon Change', '光子转换', 'フォトン・チェンジ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第2次的自己准备阶段送去墓地。这个卡名的①的效果1回合只能使用1次。 ①：可以把自己场上的表侧表示的1只「光子」怪兽或者「银河」怪兽送去墓地，从以下效果选择1个发动。把「银河眼光子龙」送去墓地发动的场合，可以选择两方。 ●原本卡名和那只怪兽不同的1只「光子」怪兽从卡组特殊召唤。 ●从卡组把「光子变身」以外的1张「光子」卡加入手卡。'),
(2618045, 'Photon Chargeman', '光子充能人', 'フォトン・チャージマン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1000, 1000, '1回合1次，自己的主要阶段时才能发动。这张卡的攻击力直到下次的自己的准备阶段时变成原本攻击力的2倍。这个效果发动的回合，这张卡不能攻击。'),
(64145892, 'Photon Circle', '光子法阵师', 'フォトン・サークラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1000, 1000, '这张卡的战斗发生的对自己的战斗伤害变成一半。'),
(1362589, 'Photon Crusher', '光子粉碎者', 'フォトン・クラッシャー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2000, NULL, '①：这张卡攻击的场合，伤害步骤结束时变成守备表示。'),
(43813459, 'Photon Current', '反射光子流', '反射光子流', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的龙族·光属性怪兽被选择作为攻击对象时才能发动。那只攻击对象怪兽的攻击力直到伤害步骤结束时上升攻击怪兽的攻击力数值。'),
(47051709, 'Photon Delta Wing', '光子三角翼飞机', 'フォトン・デルタ・ウィング', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 900, '①：这张卡召唤的场合才能发动。从手卡·卡组把1只「光子三角翼飞机」守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是光属性怪兽不能特殊召唤。 ②：自己场上有其他的「光子三角翼飞机」存在的场合，对方不能攻击宣言。'),
(73478096, 'Photon Emperor', '光子皇帝', 'フォトン・エンペラー', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡从场上以外送去墓地的场合，若这张卡以外的「光子」怪兽或「银河」怪兽在自己的场上或墓地存在则能发动。这张卡守备表示特殊召唤。 ②：这张卡召唤·特殊召唤时适用。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只光属性怪兽召唤。'),
(66607691, 'Photon Generator Unit', '光子发生装置', 'フォトン・ジェネレーター・ユニット', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上2只「电子龙」作为祭品才能发动。从自己的手卡·卡组·墓地特殊召唤1只「电子镭射龙」。'),
(15520842, 'Photon Hand', '光子之手', 'フォトン・ハンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「光子」怪兽或者「银河」怪兽存在的场合，支付1000基本分，以对方场上1只怪兽为对象才能发动。得到那只怪兽的控制权。发动时自己场上没有「银河眼光子龙」存在的场合，不是超量怪兽不能作为对象。'),
(97639441, 'Photon Jumper', '光子跳跃者', 'フォトン・ジャンパー', 'Effect Monster', 'Warrior', 'LIGHT', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤。那之后，战斗阶段结束。这个效果发动的场合，下次的自己战斗阶段跳过。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「光子」魔法·陷阱卡或「银河」魔法·陷阱卡加入手卡。'),
(35848254, 'Photon Lead', '光子引导', 'フォトン・リード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '从手卡把1只4星以下的光属性怪兽表侧攻击表示特殊召唤。'),
(38757297, 'Photon Leo', '光子狮', 'フォトン・レオ', 'Effect Monster', 'Beast', 'LIGHT', 6, 2100, 1100, '这张卡召唤成功时才能发动。对方手卡全部加入卡组洗切。那之后，对方抽出加入卡组的数量的卡。'),
(38973775, 'Photon Lizard', '光子蜥蜴', 'フォトン・リザード', 'Effect Monster', 'Dragon', 'LIGHT', 3, 900, 1200, '把这张卡解放才能发动。从卡组把1只4星以下的名字带有「光子」的怪兽加入手卡。「光子蜥蜴」的效果1回合只能使用1次。'),
(89132148, 'Photon Orbital', '光子奥比塔尔', 'フォトン・オービタル', 'Effect Monster', 'Machine', 'LIGHT', 4, 500, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只「光子」怪兽或「银河」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作持有以下效果的装备魔法卡使用给那只自己怪兽装备。 ●装备怪兽的攻击力上升500，不会被战斗破坏。 ②：把装备的这张卡送去墓地才能发动。除「光子轨道」外的1只「光子」怪兽或「银河」怪兽从卡组加入手卡。'),
(28150174, 'Photon Papilloperative', '光子蝶刺客', 'フォトン・バタフライ・アサシン', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2100, 1800, '4星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择场上守备表示存在的1只怪兽才能发动。选择的怪兽变成表侧攻击表示，那个攻击力下降600。'),
(36834155, 'Photon Pirate', '光子海盗', 'フォトン・パイレーツ', 'Effect Monster', 'Machine', 'LIGHT', 3, 1000, 1000, '自己的主要阶段时把自己墓地1只名字带有「光子」的怪兽从游戏中除外才能发动。这张卡的攻击力直到结束阶段时上升1000。「光子海盗」的效果1回合可以使用最多2次。'),
(80495985, 'Photon Sabre Tiger', '光子剑齿虎', 'フォトン・サーベルタイガー', 'Effect Monster', 'Beast', 'LIGHT', 3, 2000, 300, '这张卡召唤·反转召唤成功时，可以从卡组把1只「光子剑齿虎」加入手卡。自己场上没有这张卡以外的「光子剑齿虎」存在的场合，这张卡的攻击力下降800。'),
(17418744, 'Photon Sanctuary', '光子圣域', 'フォトン・サンクチュアリ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不是光属性怪兽不能召唤·反转召唤·特殊召唤。 ①：在自己场上把2只「光子衍生物」（雷族·光·4星·攻2000/守0）守备表示特殊召唤。这衍生物不能攻击，也不能作为同调素材。'),
(63223260, 'Photon Satellite', '光子卫星', 'フォトン・サテライト', 'Effect Monster', 'Machine', 'LIGHT', 1, NULL, NULL, '1回合1次，选择这张卡以外的自己场上1只名字带有「光子」的怪兽才能发动。选择的怪兽和这张卡变成各自等级合计的等级。'),
(9718968, 'Photon Slasher', '光子杀戮者', 'フォトン・スレイヤー', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2100, 1000, '场上有超量怪兽存在的场合，这张卡可以从手卡表侧守备表示特殊召唤。'),
(72044448, 'Photon Stream of Destruction', '破灭的光子狂流', '破滅のフォトン・ストリーム', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上有名字带有「银河眼」的怪兽存在的场合才能发动。选择场上1张卡从游戏中除外。自己场上没有「银河眼光子龙」存在的场合，这张卡不在自己回合不能发动。'),
(92661479, 'Photon Strike Bounzer', '光子飞奔保镖', 'フォトン・ストリーク・バウンサー', 'XYZ Monster', 'Warrior', 'LIGHT', 6, 2700, 2000, '6星怪兽×2 对方场上效果怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个效果无效，给与对方基本分1000分伤害。这个效果1回合只能使用1次。'),
(65367484, 'Photon Thrasher', '光子斩击者', 'フォトン・スラッシャー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2100, NULL, '这张卡不能通常召唤。自己场上没有怪兽存在的场合可以特殊召唤。 ①：自己场上有这张卡以外的怪兽存在的场合，这张卡不能攻击。'),
(8653757, 'Photon Timestop', '光子延迟', 'フォトン・リタデイション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组选1张「光子」永续魔法·永续陷阱卡或者「银河」永续魔法·永续陷阱卡加入手卡或在自己场上表侧表示放置。 ②：盖放的这张卡在对方回合被对方的效果破坏的场合，若自己场上有着「银河眼光子龙」或者有「银河眼光子龙」在作为超量素材中的超量怪兽存在则能发动。变成这个回合的结束阶段。'),
(17418745, 'Photon Token', '光子圣域', 'フォトン・サンクチュアリ', 'Token', 'Thunder', NULL, NULL, NULL, NULL, NULL),
(51589188, 'Photon Trident', '光子三叉戟', 'フォトン・トライデント', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上1只名字带有「光子」的怪兽才能发动。直到结束阶段时，选择的怪兽的攻击力上升700，向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。此外，选择的怪兽给与对方基本分战斗伤害时，可以选择场上1张魔法·陷阱卡破坏。'),
(43147039, 'Photon Vanisher', '光子驱逐者', 'フォトン・バニッシャー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 2000, NULL, '这张卡不能通常召唤。自己场上有「光子」怪兽或「银河」怪兽存在的场合可以特殊召唤。自己对「光子驱逐者」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤的场合才能发动。从卡组把1只「银河眼光子龙」加入手卡。 ②：这张卡在特殊召唤的回合不能攻击。 ③：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡战斗破坏的怪兽不去墓地而除外。'),
(9354555, 'Photon Veil', '光子帷幕', 'フォトン・ベール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己手卡让3只光属性怪兽回到卡组，可以从自己卡组把最多3只光属性·4星以下的怪兽加入手卡。2只以上加入手卡的场合，必须全部是同名怪兽。'),
(55758589, 'Photon Wyvern', '光子翼龙', 'フォトン・ワイバーン', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2500, 2000, '①：这张卡召唤·反转召唤成功的场合发动。对方场上盖放的卡全部破坏。'),
(63442604, 'Physical Double', '物理分身', '物理分身', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合才能发动。把1只持有和指定的对方怪兽相同等级·种族·属性·攻击力·守备力的「幻觉衍生物」特殊召唤。回合结束时这只衍生物破坏。'),
(70899775, 'Pianissimo', '极弱音', 'ピアニッシモ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只表侧表示怪兽的原本攻击力变成100，不会被战斗·效果破坏。'),
(69846323, 'Piercing Moray', '贯通海鳝', 'カンツウツボ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 500, '1回合1次，自己的主要阶段时把这张卡以外的自己场上1只鱼族·海龙族·水族怪兽解放才能发动。这张卡的攻击力上升600。此外，这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(21862633, 'Piercing the Darkness', '被斩裂的黑暗', '切り裂かれし闇', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己对衍生物以外的通常怪兽的召唤·特殊召唤成功的场合才能发动。自己从卡组抽1张。 ②：以下其中任意种的自己怪兽在和对方怪兽进行战斗的攻击宣言时才能发动。那只自己怪兽的攻击力直到回合结束时上升那只对方怪兽的攻击力数值。 ●5星以上的通常怪兽 ●使用通常怪兽作仪式召唤的怪兽 ●通常怪兽为素材作融合·同调·超量召唤的怪兽'),
(46497537, 'Pig Iron vs. Pen Peg', '吨锤猪打出头桩', 'トン＝トン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力·等级之内比原本数值高的数值变成原本数值。那之后，支付100的倍数的基本分（最多1000）。 ②：这张卡在墓地存在，自己基本分和对方相同的场合，自己主要阶段才能发动。这张卡在自己场上盖放。'),
(16020923, 'Pikari @Ignister', '闪亮亮＠伊格尼斯者', 'ピカリ＠イグニスター', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1200, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「“艾”」魔法·陷阱卡加入手卡。 ②：以自己场上1只「@火灵天星」怪兽为对象才能发动。那只怪兽的等级直到回合结束时变成4星。'),
(74270067, 'Pikeru''s Circle of Enchantment', '绒儿的魔法阵', 'ピケルの魔法陣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到这个回合的结束阶段前，这张卡的控制者受到的卡的效果的伤害为0。'),
(58015506, 'Pikeru''s Second Sight', '绒儿的读心术', 'ピケルの読心術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '直到对方第2个回合的结束阶段前，对方玩家的抽卡先公开再加入手卡。'),
(19153590, 'Pile Armed Dragon', '巨钻武装龙', 'パイル・アームド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 7, 2800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：把风属性或者7星以上的1只这张卡以外的龙族怪兽从手卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：从手卡·卡组把「打桩武装龙」以外的1只「武装龙」怪兽送去墓地，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，自己只能用1只怪兽攻击，作为对象的怪兽的攻击力上升送去墓地的怪兽的等级×300。'),
(20700531, 'Pilgrim of the Ice Barrier', '冰结界的修验者', '氷結界の修験者', 'Effect Monster', 'Warrior', 'WATER', 4, 1500, 1000, '①：这张卡不会被和攻击力1900以上的怪兽的战斗破坏。'),
(45742626, 'Pilgrim Reaper', '巡死神 收割者', '巡死神リーパー', 'XYZ Monster', 'Zombie', 'DARK', 6, -1, -1, '6星怪兽×2 「巡死神 收割者」的②的效果1回合只能使用1次。 ①：这张卡的攻击力·守备力上升双方墓地的暗属性怪兽数量×200。 ②：把这张卡1个超量素材取除才能发动。从双方卡组上面把5张卡送去墓地。'),
(71175527, 'Pilica, Descendant of Gusto', '薰风的神裔 皮莉佳', 'ガスタの神裔 ピリカ', 'Effect Monster', 'Psychic', 'WIND', 3, 1000, 1500, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时，以自己墓地1只风属性调整为对象才能发动。那只风属性怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是风属性怪兽不能特殊召唤。'),
(20357457, 'Pillar of the Future - Cyanos', '未来之柱－奇亚诺斯', '未来の柱－キアノス', 'Effect Monster', 'Machine', 'LIGHT', 1, 500, 1500, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1只「闪刀姬-露世」特殊召唤。这个回合，自己不是机械族怪兽不能从额外卡组特殊召唤。 ③：把墓地的这张卡除外才能发动。选自己的墓地·除外状态的1只「闪刀姬-露世」加入手卡或特殊召唤。'),
(26185991, 'Pinch Hopper', '代打蝗虫', '代打バッター', 'Effect Monster', 'Insect', 'EARTH', 4, 1000, 1200, '①：这张卡从自己场上送去墓地时才能发动。从手卡把1只昆虫族怪兽特殊召唤。'),
(90669991, 'Pineapple Blast', '菠萝爆弹', 'パイナップル爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己召唤怪兽成功时发动。若对方场上的怪兽数比自己控制的怪兽数多，则破坏对方场上的怪兽直到与自己的怪兽数量相同为止。破坏哪些怪兽由对方选择。'),
(67445676, 'Pinecono', '松果小矮人', 'マツボックル', 'Effect Monster', 'Plant', 'EARTH', 1, 400, 200, '这张卡被「小矮人橡子」的效果送去墓地的场合，这张卡可以从墓地特殊召唤。'),
(94431029, 'Pinpoint Dash', '一点冲夺法', 'ピンポイント奪取', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：双方各自选自身的额外卡组1张里侧表示的卡。那些卡给双方确认，相同种类（融合·同调·超量·连接）的场合，对方选的卡送去墓地，自己选的卡特殊召唤。并且原本的种族·属性相同的场合，再让对方失去自身选的卡的攻击力数值的基本分。不同种类的场合，自己选的卡送去墓地，对方把自身选的卡特殊召唤。');